package dev.rain.laundry.ui

import kotlin.math.max
import kotlin.math.roundToInt

internal const val MAX_SPLASH_IMAGES = 12
internal const val SPLASH_IMAGE_MAX_EDGE = 1920
internal const val DEFAULT_SPLASH_DURATION_MS = 700
internal const val MIN_SPLASH_DURATION_MS = 100
internal const val MAX_SPLASH_DURATION_MS = 60_000

internal val defaultSplashImages: List<String> = listOf(
    "default:splash_mascot_1",
    "default:splash_mascot_2"
)

private val splashImageName = Regex("splash_[a-f0-9]{32}\\.(jpg|png)")

/** Preferences contain only names generated by the private image store, never external paths or URIs. */
internal fun normalizeSplashImageNames(images: List<String>): List<String> =
    images.asSequence().filter { splashImageName.matches(it) }.distinct().take(MAX_SPLASH_IMAGES).toList()

internal fun effectiveSplashImages(custom: List<String>): List<String> =
    normalizeSplashImageNames(custom).ifEmpty { defaultSplashImages }

internal fun normalizeSplashDurationMs(value: Int): Int =
    value.coerceIn(MIN_SPLASH_DURATION_MS, MAX_SPLASH_DURATION_MS)

internal fun savedSplashDurationMs(value: Int?): Int =
    value?.takeIf { it in MIN_SPLASH_DURATION_MS..MAX_SPLASH_DURATION_MS } ?: DEFAULT_SPLASH_DURATION_MS

/** Returns the current and next positions; corrupt counters restart the chosen sequence. */
internal fun splashSequenceStep(savedIndex: Int?, imageCount: Int): Pair<Int, Int> {
    require(imageCount > 0)
    val current = savedIndex?.takeIf { it in 0 until imageCount } ?: 0
    return current to (current + 1) % imageCount
}

// Newline is unambiguous because the private file-name grammar excludes control characters.
internal fun encodeSplashImages(images: List<String>): String = normalizeSplashImageNames(images).joinToString("\n")

internal fun decodeSplashImages(saved: String?): List<String> =
    if (saved == null || saved.length > 1024) emptyList()
    else normalizeSplashImageNames(saved.split('\n'))

/** Bound both the first decode's area and edge, then resize precisely without losing small portraits. */
internal fun splashSampleSize(width: Int, height: Int, maxEdge: Int = SPLASH_IMAGE_MAX_EDGE): Int {
    require(width > 0 && height > 0 && maxEdge > 0)
    var sample = 1
    while ((max(width, height).toLong() + sample - 1) / sample > maxEdge.toLong() * 2 ||
        ((width.toLong() + sample - 1) / sample) * ((height.toLong() + sample - 1) / sample) > 4_000_000L) {
        sample *= 2
    }
    return sample
}

internal fun splashImageDimensions(width: Int, height: Int, maxEdge: Int = SPLASH_IMAGE_MAX_EDGE): Pair<Int, Int> {
    require(width > 0 && height > 0 && maxEdge > 0)
    val scale = minOf(1.0, maxEdge.toDouble() / max(width, height))
    return maxOf(1, (width * scale).roundToInt()) to maxOf(1, (height * scale).roundToInt())
}

internal data class SplashImageOrientation(val degrees: Float, val mirror: Boolean)

/** EXIF orientations 5 and 7 include both a rotation and a reflection. */
internal fun splashImageOrientation(exif: Int): SplashImageOrientation = when (exif) {
    2 -> SplashImageOrientation(0f, true)
    3 -> SplashImageOrientation(180f, false)
    4 -> SplashImageOrientation(180f, true)
    5 -> SplashImageOrientation(90f, true)
    6 -> SplashImageOrientation(90f, false)
    7 -> SplashImageOrientation(270f, true)
    8 -> SplashImageOrientation(270f, false)
    else -> SplashImageOrientation(0f, false)
}
